parameters.text:
You are an expert OCR and data extraction assistant for academic question papers. 
Carefully analyze the provided document and extract all text, tables, and structural elements into a rigidly formatted JSON object.
Use the exact keys provided in the structure below. Do NOT output any markdown tags (like ```json), give only the raw string.

If the paper is divided into PART-A and PART-B, utilize the "part_a" and "part_b" structures. 
If it is a single table of questions (like an Internal Assessment), utilize the "questions_table" structure instead.

Strictly adhere to this JSON structure format:
{
  "institution_header": ["string array of top header lines"],
  "exam_details": {
    "examination_name": "string",
    "duration": "string",
    "course_code": "string",
    "maximum_marks": "string",
    "subject": "string"
  },
  "instructions": ["string array of notes/instructions"],
  "part_a": {
    "heading": "string",
    "table_headers": ["string array"],
    "questions": [
      {
        "Q.No.": "string",
        "Question": "string",
        "BL": "string",
        "CO": "string",
        "PO": "string",
        "Marks": "string"
      }
    ]
  },
  "part_b": {
    "heading": "string",
    "table_headers": ["string array"],
    "modules": [
      {
        "heading": "string value (e.g., Module-1)",
        "rows": [
          {
            "Q.No.": "optional string",
            "sub_question": "optional string (e.g., a, b)",
            "Question": "optional string",
            "BL": "optional string",
            "CO": "optional string",
            "PO": "optional string",
            "Marks": "optional string",
            "separator": "optional string (use only if there's an 'OR' separator)"
          }
        ]
      }
    ]
  },
  "questions_table": {
    "table_headers": ["string array"],
    "questions": [
       { "Q.No.": "string", "Question": "string", "BL": "string", "CO": "string", "PO": "string", "Marks": "string" }
    ]
  },
  "footer_markers": ["string array of footer texts like page numbers or codes"]
}

parameters.jsCode:
const webhookData = $node["Webhook"].json.body; 

let aiText = "";
if (Array.isArray($input.item.json) && $input.item.json[0]?.content) {
    aiText = $input.item.json[0].content.parts[0].text;
} else if ($input.item.json.content?.parts) {
    aiText = $input.item.json.content.parts[0].text;
} else {
    aiText = $input.item.json.text || $input.item.json.output || "";
}

aiText = aiText.replace(/```json/g, '').replace(/```/g, '').trim();
const parsedResult = JSON.parse(aiText);

return {
  json: {
    institution_name: parsedResult.institution_header ? parsedResult.institution_header[0] : null,
    examination_name: parsedResult.exam_details?.examination_name || null,
    subject_name: parsedResult.exam_details?.subject || null,
    subject_code: webhookData.subject_code || null,
    exam_year: parseInt(webhookData.exam_year) || null,
    paper_type: webhookData.paper_type || null,
    duration: parsedResult.exam_details?.duration || null,
    maximum_marks: parseInt(String(parsedResult.exam_details?.maximum_marks).replace(/\D/g, '')) || null,
    upload_role: webhookData.role || null
  }
};
// Now this node ONLY outputs database columns! Auto-map will work perfectly.

const paperId = $input.item.json.id; 
const subjectCode = $node["Webhook"].json.body.subject_code;

// NOTICE the exact lowercase 'd' here to match your setup exactly!
const geminiData = $node["Analyze document"].json;

let aiText = "";
if (Array.isArray(geminiData) && geminiData[0]?.content) {
    aiText = geminiData[0].content.parts[0].text;
} else if (geminiData.content?.parts) {
    aiText = geminiData.content.parts[0].text;
} else {
    aiText = geminiData.text || geminiData.output || "";
}

aiText = aiText.replace(/```json/g, '').replace(/```/g, '').trim();
const aiData = JSON.parse(aiText);

let dbQuestions = [];

const processQuestion = (q, part, moduleTitle) => {
  if(!q.Question) return;
  dbQuestions.push({
    paper_id: paperId,
    subject_code: subjectCode,
    part: part,
    module: moduleTitle || null,
    q_no: q["Q.No."] || null,
    sub_question: q.sub_question || null,
    question_text: q.Question,
    blooms_level: parseInt(String(q.BL).replace(/\D/g, '')) || null,
    course_outcome: q.CO || null,
    program_outcome: q.PO || null,
    marks: parseInt(q.Marks) || null
  });
};

if (aiData.questions_table?.questions) {
  aiData.questions_table.questions.forEach(q => processQuestion(q, 'General', null));
}
if (aiData.part_a?.questions) {
  aiData.part_a.questions.forEach(q => processQuestion(q, 'Part-A', null));
}
if (aiData.part_b?.modules) {
  aiData.part_b.modules.forEach(mod => {
    mod.rows.forEach(q => processQuestion(q, 'Part-B', mod.heading));
  });
}

return dbQuestions.map(item => ({ json: item }));

return [
  {
    json: {
      status: "ok",
      service: "n8n",
      workflow: "PBL_Vision-workflow",
      timestamp: new Date().toISOString()
    }
  }
];
